INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (8,8,'["Pouvez-vous décrire concrètement les outils de conception architecturale que vous maîtrisez (AutoCAD, Revit, ArchiCAD...) et donner un exemple de projet où vous les avez utilisés ?", "Comment procédez-vous pour vérifier la conformité d''un projet architectural aux normes de construction en vigueur au Maroc, notamment le RPS 2000 ou le CPTED ?", "Dans le cadre d''un projet de bâtiment public, quelles sont selon vous les étapes clés d''un dossier d''appel d''offres sur le plan architectural, de l''esquisse au DCE ?", "Votre score de correspondance avec ce poste est de 34 % : quelles compétences spécifiques à ce poste estimez-vous devoir encore développer, et comment comptez-vous y remédier ?", "En 6 ans d''expérience, quel est le projet dont vous êtes le plus fier et quel a été précisément votre rôle dans sa réalisation ?", "Avez-vous déjà travaillé sur des projets d''aménagement territorial ou urbain, et si oui, en collaboration avec quels types d''acteurs institutionnels ?", "Pourquoi postulez-vous à un poste d''Assistant Architecte alors que vous avez 6 ans d''expérience et un Master d''une grande école d''ingénieurs ?", "Où vous voyez-vous professionnellement dans 5 ans, et en quoi l''ADER s''inscrit-elle dans cette trajectoire ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans la région ?", "Quelle est votre perception du rôle d''un architecte au sein d''un établissement public par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:27:00.555286') ON CONFLICT (id) DO NOTHING;